uint32_t gba_idle_loop_lookup(const char *gamepak_code) {
    for (size_t i = 0; i < sizeof(GBA_IDLE_LOOPS) / sizeof(GBA_IDLE_LOOPS[0]); ++i) {
        if (memcmp(GBA_IDLE_LOOPS[i].code, gamepak_code, 4) == 0) {
            return GBA_IDLE_LOOPS[i].pc;
        }
    }
    return 0;   // unknown game: leave gpSP's own table alone
}

uint32_t gba_exec_cycles_lookup(const char *gamepak_code) {
    for (size_t i = 0; i < sizeof(GBA_IDLE_LOOPS) / sizeof(GBA_IDLE_LOOPS[0]); ++i) {
        if (memcmp(GBA_IDLE_LOOPS[i].code, gamepak_code, 4) == 0) {
            return GBA_IDLE_LOOPS[i].exec;
        }
    }
    return 0;
}
